        "nombre_aysen": "$s2.name",
        "marca_aysen": "$s2.brand",
        "precio_aysen": "$s2.price_clp",
        "ram_aysen": "$s2.attributes.ram_gb",
        "almacenamiento_aysen": "$s2.attributes.almacenamiento_gb",
        "bateria_aysen": "$s2.attributes.bateria_mah",
        "camara_aysen": "$s2.attributes.camara_mp",
        "pantalla_aysen": "$s2.attributes.pantalla_pulgadas",
        "rating_aysen": "$s2.avg_rating",
        "resenas_aysen": "$s3",
        "alt1_nombre": "$s1.0.name",
        "alt1_precio": "$s1.0.price_clp",
        "alt1_id": "$s1.0.id",
        "alt2_nombre": "$s1.1.name",
        "alt2_precio": "$s1.1.price_clp",
        "alt2_id": "$s1.1.id"
      }
    }
  ]
}
